namespace backend.Entities.Friendships;

// Online-only: created and changed through ordinary endpoints, not synced.
public class Friendship
{
    // Generated by the server.
    public Guid Id { get; private set; }
    // Both ids come from the JWT "sub" claim (requester) and a validated receiver, never trusted from a payload.
    public Guid RequesterId { get; private set; }
    public Guid ReceiverId { get; private set; }
    public FriendshipStatus Status { get; private set; } = FriendshipStatus.Pending;
    // Who blocked, so only they can lift the block.
    public Guid? BlockedById { get; private set; }
    public DateTime CreatedAt { get; private set; }

    public static Friendship Create(Guid requesterId, Guid receiverId, DateTime now)
    {
        Guard.NotEmpty(requesterId, "RequesterId");
        Guard.NotEmpty(receiverId, "ReceiverId");
        if (requesterId == receiverId) throw new ArgumentException("A user cannot befriend themselves.");

        return new Friendship
        {
            Id = Guid.NewGuid(),
            RequesterId = requesterId,
            ReceiverId = receiverId,
            CreatedAt = now
        };
    }

    // Only the receiver can accept, and only a pending request.
    public void Accept(Guid actorId)
    {
        if (actorId != ReceiverId) throw new ArgumentException("Only the receiver can accept a friend request.");
        if (Status != FriendshipStatus.Pending) throw new InvalidOperationException("Only a pending request can be accepted.");
        Status = FriendshipStatus.Accepted;
    }

    // Either participant can block, from any state. Blocking again keeps the original blocker.
    public void Block(Guid actorId)
    {
        if (!IsParticipant(actorId)) throw new ArgumentException("Only a participant can block.");
        if (Status == FriendshipStatus.Blocked) return;
        Status = FriendshipStatus.Blocked;
        BlockedById = actorId;
    }

    // Cancelling, declining, unfriending and unblocking all delete the row. A block can only be lifted by the blocker.
    public bool CanRemove(Guid actorId)
        => IsParticipant(actorId) && (Status != FriendshipStatus.Blocked || BlockedById == actorId);

    private bool IsParticipant(Guid userId) => userId == RequesterId || userId == ReceiverId;
}

public enum FriendshipStatus { Pending, Accepted, Blocked }
